const words=(s:string)=>s.toLowerCase().replace(/[^a-z0-9 ]+/g,' ').split(/\s+/).filter(Boolean);
export function searchDiy(query:string,category:DiyCategory|'All'='All',gate:DiyGate|'all'='all',list:DiyGuide[]=diyGuides){
 const base=list.filter(x=>(category==='All'||x.category===category)&&(gate==='all'||x.gate===gate)),q=words(query);if(!q.length)return base;
 return base.map(x=>{const t=words(x.title),h=words([x.title,x.summary,x.category,x.tools.join(' '),x.materials.join(' '),x.steps.join(' ')].join(' '));let s=0;for(const w of q){if(t.includes(w))s+=5;else if(t.some(y=>y.startsWith(w)&&w.length>2))s+=3;if(h.includes(w))s+=2;}return {x,s};}).filter(r=>r.s>0).sort((a,b)=>b.s-a.s).map(r=>r.x);
}
